    printf("Selected Items: ");
    int cur_w = W;
    for (int i = n; i > 0 && cur_w > 0; i--) {
        if (dp[i][cur_w] != dp[i - 1][cur_w]) {
            printf("[Item %d: w=%d, v=%d] ", i, weights[i], values[i]);
            cur_w -= weights[i];
        }
    }
    putchar('\n');
}

